const cachePrefix = 'graspmemoedu-static:' + APP_ROOT.pathname + ':';
const cacheName = cachePrefix + ASSET_VERSION;
const assetDestinations = new Set(['script', 'style', 'image', 'worker']);

async function openAssetCache() {
  try { return await caches.open(cacheName); }
  catch { return null; }
}

async function storeAsset(cache, url, response, expected) {
  if (response.status !== 200 || response.redirected ||
      /(?:^|,)\s*(?:private|no-store)\b/i.test(response.headers.get('Cache-Control') || '')) return;
  // Pages serves the same path under every query version. During a deployment,
  // never pin newer bytes to an older immutable URL.
  const text = (await response.clone().text()).replace(/\r\n?/g, '\n');
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  const hex = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
  if (hex === expected) await cache.put(url.href, response);
}

function serveAsset(event, url, expected) {
  const cache = openAssetCache();
  const cached = cache.then(async store => {
    try { return await store?.match(url.href); }
    catch { return undefined; }
  });
  const network = cached.then(hit => hit ? null : fetch(event.request, {credentials: 'omit'}));
  event.waitUntil(Promise.all([cache, network]).then(([store, response]) => {
    if (store && response) return storeAsset(store, url, response.clone(), expected);
  }).catch(() => {}));
  event.respondWith(cached.then(hit => hit || network));
}

